43	+import React from "react";
44	+import {
45	+  HyperlinkButton,
46	+  T,
47	+  TLShape,
48	+  TLShapeId,
49	+  useEditor,
50	+  useValue,
51	+} from "tldraw";
52	+
53	+type TextLink = { id: TLShapeId; url: string; left: number; top: number };
54	+
55	+// Matches the hit area of tldraw's .tl-hyperlink-button.
56	+const BUTTON_SIZE = 44;
57	+
58	+// meta is unvalidated, so this is the only guard before an href. Returning the
59	+// parsed form keeps the href identical to what passed validation.
60	+export const getTextShapeLinkUrl = (shape: TLShape): string | undefined => {
61	+  if (shape.type !== "text") return undefined;
62	+  const { url } = shape.meta;
63	+  if (typeof url !== "string" || !T.linkUrl.isValid(url)) return undefined;
64	+  try {
65	+    // linkUrl resolves relative paths against a dummy origin; only absolute URLs render.
66	+    return new URL(url).href;
67	+  } catch {
68	+    return undefined;
69	+  }
70	+};
71	+
72	+// Text bounds hug the glyphs, so the icon sits just outside the right edge
73	+// rather than in the shape corner where geo shapes draw it.
74	+export const TextLinkOverlay = (): JSX.Element => {
75	+  const editor = useEditor();
76	+  const links = useValue<TextLink[]>(
77	+    "textShapeLinks",
78	+    () => {
79	+      const viewport = editor.getViewportPageBounds();
80	+      return editor.getCurrentPageShapes().flatMap((shape) => {
81	+        const url = getTextShapeLinkUrl(shape);
82	+        if (!url) return [];
83	+        const bounds = editor.getShapePageBounds(shape.id);
84	+        if (!bounds || !viewport.collides(bounds)) return [];
85	+        const anchor = editor.pageToViewport({
86	+          x: bounds.maxX,
87	+          y: bounds.midY,
88	+        });
89	+        return [
90	+          {
91	+            id: shape.id,
92	+            url,
93	+            left: anchor.x,
94	+            top: anchor.y - BUTTON_SIZE / 2,
95	+          },
96	+        ];
97	+      });
98	+    },
99	+    [editor],
100	+  );
101	+  const zoomLevel = useValue("zoomLevel", () => editor.getZoomLevel(), [
102	+    editor,
103	+  ]);
104	+
105	+  return (
106	+    <div style={{ position: "absolute", inset: 0, pointerEvents: "none" }}>
107	+      {links.map(({ id, url, left, top }) => (
108	+        <div
109	+          key={id}
110	+          style={{
111	+            position: "absolute",
112	+            left: `${left}px`,
113	+            top: `${top}px`,
114	+            width: `${BUTTON_SIZE}px`,
115	+            height: `${BUTTON_SIZE}px`,
116	+          }}
117	+        >
118	+          <HyperlinkButton url={url} zoomLevel={zoomLevel} />
119	+        </div>
120	+      ))}
121	+    </div>
122	+  );
123	+};
