130	+import { describe, expect, it } from "vitest";
131	+import { createTLSchema, TLShape } from "tldraw";
132	+import { getTextShapeLinkUrl } from "~/components/canvas/overlays/TextLinkOverlay";
133	+
134	+const makeShape = ({
135	+  type = "text",
136	+  meta = {},
137	+}: {
138	+  type?: string;
139	+  meta?: Record<string, unknown>;
140	+} = {}): TLShape =>
141	+  ({
142	+    id: "shape:t1",
143	+    typeName: "shape",
144	+    type,
145	+    x: 0,
146	+    y: 0,
147	+    rotation: 0,
148	+    index: "a1",
149	+    parentId: "page:page",
150	+    isLocked: false,
151	+    opacity: 1,
152	+    meta,
153	+    props: {
154	+      color: "black",
155	+      size: "m",
156	+      font: "draw",
157	+      textAlign: "middle",
158	+      w: 100,
159	+      text: "hello",
160	+      scale: 1,
161	+      autoSize: true,
162	+    },
163	+  }) as unknown as TLShape;
164	+
165	+const withUrl = (url: unknown): TLShape => makeShape({ meta: { url } });
166	+
167	+describe("getTextShapeLinkUrl", () => {
168	+  it("returns the parsed href for a valid link", () => {
169	+    expect(getTextShapeLinkUrl(withUrl("https://Example.com"))).toBe(
170	+      "https://example.com/",
171	+    );
172	+    expect(getTextShapeLinkUrl(withUrl("mailto:a@b.co"))).toBe("mailto:a@b.co");
173	+  });
174	+
175	+  it("treats a missing or cleared link as no link", () => {
176	+    expect(getTextShapeLinkUrl(makeShape())).toBeUndefined();
177	+    expect(getTextShapeLinkUrl(withUrl(""))).toBeUndefined();
178	+    expect(getTextShapeLinkUrl(withUrl(42))).toBeUndefined();
179	+  });
180	+
181	+  it("ignores links on shapes other than text", () => {
182	+    const geo = makeShape({
183	+      type: "geo",
184	+      meta: { url: "https://example.com" },
185	+    });
186	+    expect(getTextShapeLinkUrl(geo)).toBeUndefined();
187	+  });
188	+
189	+  // meta has no schema, so a collaborator or API writer can store anything here.
190	+  it("rejects protocols that could run script", () => {
191	+    expect(getTextShapeLinkUrl(withUrl("javascript:alert(1)"))).toBeUndefined();
192	+    expect(
193	+      getTextShapeLinkUrl(withUrl(" javascript:alert(1)")),
194	+    ).toBeUndefined();
195	+    expect(getTextShapeLinkUrl(withUrl("data:text/html,x"))).toBeUndefined();
196	+  });
197	+
198	+  it("rejects relative URLs that linkUrl resolves against a dummy origin", () => {
199	+    expect(getTextShapeLinkUrl(withUrl("/page"))).toBeUndefined();
200	+    expect(getTextShapeLinkUrl(withUrl("//evil.example/x"))).toBeUndefined();
201	+  });
202	+});
203	+
204	+describe("text shape link persistence", () => {
205	+  // The stock schema is what older extension builds and the sync worker use.
206	+  const stockSchema = createTLSchema();
207	+
208	+  it("validates a text shape carrying meta.url against the stock schema", () => {
209	+    expect(() =>
210	+      stockSchema.validateRecord(
211	+        {} as never,
212	+        withUrl("https://example.com") as never,
213	+        "initialize",
214	+        null,
215	+      ),
216	+    ).not.toThrow();
217	+  });
218	+
219	+  it("round-trips meta.url through a snapshot load with no migration", () => {
220	+    const shape = withUrl("https://example.com");
221	+    const migrated = stockSchema.migrateStoreSnapshot({
222	+      store: { [shape.id]: shape },
223	+      schema: stockSchema.serialize(),
224	+    });
225	+    expect(migrated.type).toBe("success");
226	+    const loaded = (migrated as unknown as { value: Record<string, TLShape> })
227	+      .value[shape.id];
228	+    expect(loaded.meta.url).toBe("https://example.com");
229	+  });
230	+});
